// The 44 binding scenarios from the detection audit. Each is { name, about, open, run, expect }:
//   open:   options for app.open() (devices plugged before load, gesture gate, seeded profile, query)
//   run:    async (page, h) => observed state; h is ./gamepad.js plus play() and frames()
//   expect: observed => true, or a short description of what went wrong.
// The expectations encode the TARGET behavior from the audit's proposed detection algorithm
// (3-frame arming, 250 ms grace window, 1.25x margin, hat exclusion, unreported-device handling,
// per-pad lazy baselines, release-before-press buttons, 50 ms debounce, slot-aware twins, 8 s hint).
const h = require("./gamepad");
const { DEV, AX, HAT_IDLE, ms, move, hold, btn, press, plug, unplug, noise, throwAxis, stickXY } = h;

const toStick = page => h.toType(page, "Stick");
const toType = (page, name) => h.toType(page, name);
const toButton = page => h.toType(page, "Button");
const bound = (s, axes, inv) => {
  if (!s || s.stage !== "name") return `never finished (stage ${s && s.stage}, step ${s && s.step}, axes ${JSON.stringify(s && s.axes)})`;
  for (const k in axes) if (s.axes[k] !== axes[k] || (inv && s.inv[k] !== inv[k])) return `bound ${JSON.stringify(s.axes)} inv ${JSON.stringify(s.inv)}`;
  return true;
};
const boundBtn = (s, b, slot) => !s || s.stage !== "name" ? `never finished (stage ${s && s.stage})` : s.button !== b || (slot != null && s.dev.slot !== slot) ? `bound button ${s.button} on slot ${s.dev.slot}` : true;
const twinProfile = () => ({ savedAt: Date.now(), settings: {}, widgets: [
  { id: "L", type: "stick", label: "Left Stick", x: 100, y: 100, match: DEV.virpil().id, nth: 0, slot: 0, axes: { x: 0, y: 1 }, inv: { x: false, y: true }, size: 1 },
  { id: "R", type: "stick", label: "Right Stick", x: 400, y: 100, match: DEV.virpil().id, nth: 1, slot: 1, axes: { x: 0, y: 1 }, inv: { x: false, y: true }, size: 1 }] });

module.exports = [
  // ---------- axes ----------
  { name: "stick-basic", about: "Clean X right then Y forward (raw -1)",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, stickXY(0)); return h.wizState(page); },
    expect: s => bound(s, { x: AX.x, y: AX.y }, { x: false, y: true }) },
  { name: "twist-bleed-small", about: "X right with twist bleeding 0.45 in step with X",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, move(0, 5, ms(300), { 0: [0, 1], 5: [0, 0.45] })); return h.wizState(page); },
    expect: s => s.step === 1 && s.axes.x === AX.x ? true : `bound ${JSON.stringify(s.axes)}` },
  { name: "twist-bleed-leads", about: "Grabbing the grip twists it 0.7 in the first 60 ms while X travels to 1 over 300 ms",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, move(0, 5, ms(300), { 0: [0, 1], 5: [0, 0.7] }, { dur: { 5: ms(60) } })); return h.wizState(page); },
    expect: s => s.step === 1 && s.axes.x === AX.x ? true : `bound x=${s.axes.x} (twist is ${AX.twist}) inv=${s.inv.x}` },
  { name: "axis-twist-xy-bleed", about: "Single axis = twist; twisting knocks X to 0.65 in the first 100 ms",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toType(page, "Single axis"); await h.play(page, move(0, 5, ms(300), { 5: [0, 1], 0: [0, 0.65] }, { dur: { 0: ms(100) } })); return h.wizState(page); },
    expect: s => bound(s, { a: AX.twist }, { a: false }) },
  { name: "slow-throw", about: "X pushed right over 2 s while Y drifts to 0.3",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, move(0, 5, ms(2000), { 0: [0, 1], 1: [0, 0.3] })); return h.wizState(page); },
    expect: s => s.step === 1 && s.axes.x === AX.x && !s.inv.x ? true : `bound ${JSON.stringify(s.axes)} inv ${JSON.stringify(s.inv)}` },
  { name: "quick-flick", about: "X flicked right and released within 150 ms",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, [...move(0, 5, ms(70), { 0: [0, 1] }), ...move(0, 6 + ms(70), ms(80), { 0: [1, 0] })]); return h.wizState(page); },
    expect: s => s.step === 1 && s.axes.x === AX.x && !s.inv.x ? true : `bound ${JSON.stringify(s.axes)} inv ${JSON.stringify(s.inv)}` },
  { name: "pedals-basic", about: "T-Rudder, brakes rest at -1 and are already reported",
    open: { devices: [DEV.trudder()] },
    run: async page => { await toType(page, "Pedals"); await h.play(page, [...throwAxis(0, 5, AX.rudder, 0, 1), ...throwAxis(0, 5 + ms(900), AX.bl, -1, 1), ...throwAxis(0, 5 + ms(1800), AX.br, -1, 1)]); return h.wizState(page); },
    expect: s => bound(s, { r: AX.rudder, bl: AX.bl, br: AX.br }, { r: false, bl: false, br: false }) },
  { name: "pedals-zero-until-report", about: "T-Rudder axes read 0 until its first HID report (brakes then jump to -1)",
    open: { devices: [DEV.trudder({ zeroUntilReport: true })] },
    run: async page => { await toType(page, "Pedals"); await h.play(page, throwAxis(0, 5, AX.rudder, 0, 1)); return h.wizState(page); },
    expect: s => s.step >= 1 && s.axes.r === AX.rudder && s.inv.r === false ? true : `rudder bound to axis ${s.axes.r} inv=${s.inv.r}` },
  { name: "throttle-rest-back", about: "Throttle rests at raw -1 (back), pushed to +1",
    open: { devices: [DEV.throttle(-1)] },
    run: async page => { await toType(page, "Throttle"); await h.play(page, move(0, 5, ms(400), { 2: [-1, 1] })); return h.wizState(page); },
    expect: s => bound(s, { t: AX.thr }, { t: false }) },
  { name: "throttle-forward-is-negative", about: "Throttle rests at raw +1 (back), forward is raw -1",
    open: { devices: [DEV.throttle(1)] },
    run: async page => { await toType(page, "Throttle"); await h.play(page, move(0, 5, ms(400), { 2: [1, -1] })); return h.wizState(page); },
    expect: s => bound(s, { t: AX.thr }, { t: true }) },
  { name: "throttle-left-at-forward", about: "Throttle already at full forward (raw +1) when the step opens; user pulls back then pushes forward",
    open: { devices: [DEV.throttle(1)] },
    run: async page => { await toType(page, "Throttle"); await h.play(page, [...move(0, 5, ms(400), { 2: [1, -1] }), ...move(0, 5 + ms(500), ms(400), { 2: [-1, 1] })]); return h.wizState(page); },
    expect: s => bound(s, { t: AX.thr }, { t: false }) },
  { name: "throttle-zero-until-report", about: "Throttle at raw -1 reads 0 until first report; user nudges it 5% then pushes",
    open: { devices: [DEV.throttle(-1, { zeroUntilReport: true })] },
    run: async page => { await toType(page, "Throttle"); await h.play(page, [...move(0, 5, ms(100), { 2: [-1, -0.95] }), ...move(0, 5 + ms(600), ms(400), { 2: [-0.95, 1] })]); return h.wizState(page); },
    expect: s => bound(s, { t: AX.thr }, { t: false }) },
  { name: "hat-bump", about: "Hat as axis 9 (idle 1.2857); thumb brushes hat up for 100 ms before X right",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, [...hold(0, 5, ms(100), { 9: -1 }), ...hold(0, 5 + ms(100), 2, { 9: HAT_IDLE }), ...throwAxis(0, 5 + ms(200), AX.x, 0, 1)]); return h.wizState(page); },
    expect: s => s.step >= 1 && s.axes.x === AX.x ? true : `bound x=${s.axes.x} inv=${s.inv.x}` },
  { name: "hat-zero-until-report", about: "Stick axes read 0 until first report; hat then jumps to its 1.2857 idle as X starts moving",
    open: { devices: [DEV.virpil({ zeroUntilReport: true })] },
    run: async page => { await toStick(page); await h.play(page, throwAxis(0, 5, AX.x, 0, 1)); return h.wizState(page); },
    expect: s => s.step >= 1 && s.axes.x === AX.x ? true : `bound x=${s.axes.x} inv=${s.inv.x}` },
  { name: "jitter-idle", about: "±0.04 noise on every axis for 3 s, nobody touching anything",
    open: { devices: [DEV.virpil(), DEV.trudder()] },
    run: async page => { await toStick(page); await h.play(page, [...noise(0, 5, ms(3000), [0, 1, 2, 3, 4, 5, 6], [0, 0, 0, 0, 0, 0, 0], 0.04), ...noise(1, 5, ms(3000), [0, 1, 5], [-1, -1, 0], 0.04, 3)]); return h.wizState(page); },
    expect: s => s.step === 0 ? true : `bound ${JSON.stringify(s.axes)} with nobody touching` },
  { name: "noise-plus-move", about: "±0.1 noise everywhere, real X throw",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, move(0, 5, ms(300), { 0: [0, 1], 1: [0, 0], 5: [0, 0] }, { noise: 0.1 })); return h.wizState(page); },
    expect: s => s.step === 1 && s.axes.x === AX.x && !s.inv.x ? true : `bound ${JSON.stringify(s.axes)}` },
  { name: "single-frame-spike", about: "Slider axis 6 glitches to 0.75 for one frame, then real X throw",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, [...hold(0, 5, 1, { 6: 0.75 }), ...hold(0, 6, 1, { 6: 0 }), ...throwAxis(0, 20, AX.x, 0, 1)]); return h.wizState(page); },
    expect: s => s.step >= 1 && s.axes.x === AX.x ? true : `bound x=${s.axes.x}` },
  { name: "carryover-into-next-step", about: "Pushing the right rudder pedal also rolls the right toe brake to -0.2 after rudder passes 0.6; the left-brake step must not complete from that",
    open: { devices: [DEV.trudder()] },
    run: async page => { await toType(page, "Pedals"); await h.play(page, [...move(0, 5, ms(300), { 5: [0, 1], 1: [-1, -0.2] }, { delay: { 1: ms(150) }, dur: { 1: ms(250) } }),
      ...move(0, 5 + ms(600), ms(200), { 5: [1, 0], 1: [-0.2, -1] }), ...throwAxis(0, 5 + ms(1200), AX.bl, -1, 1)]); return h.wizState(page); },
    expect: s => s.step >= 2 && s.axes.bl === AX.bl && s.inv.bl === false ? true : `left-brake step bound ${JSON.stringify(s.axes)} inv ${JSON.stringify(s.inv)}` },
  { name: "trigger-standard-single-axis", about: "Xbox (standard mapping) trigger is buttons[7].value only; user picks Single axis and pulls it",
    open: { devices: [DEV.xbox()] },
    run: async page => { await toType(page, "Single axis"); const tl = []; for (let f = 0; f <= ms(400); f++) tl.push(btn(0, 5 + f, 7, f / ms(400))); await h.play(page, tl); return h.wizState(page); },
    expect: s => s.stage === "name" ? true : `never finished: analog trigger exposed only as a button value is invisible to the axis wizard` },
  { name: "trigger-as-button", about: "Analog trigger ramps through buttons[7].value; button wizard",
    open: { devices: [DEV.xbox()] },
    run: async page => { await toButton(page); const tl = []; for (let f = 0; f <= ms(300); f++) tl.push(btn(0, 5 + f, 7, f / ms(300))); await h.play(page, tl); return h.wizState(page); },
    expect: s => boundBtn(s, 7) },
  // ---------- buttons ----------
  { name: "button-basic", about: "Press button 3",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toButton(page); await h.play(page, press(0, 5, 3)); return h.wizState(page); },
    expect: s => boundBtn(s, 3) },
  { name: "button-held-at-open", about: "Button 3 already held when the step opens; user releases and presses it again",
    open: { devices: [DEV.virpil({ buttons: Array.from({ length: 32 }, (_, i) => i === 3 ? 1 : 0) })] },
    run: async page => { await toButton(page); await h.play(page, [btn(0, 5, 3, false), ...press(0, 20, 3)]); return h.wizState(page); },
    expect: s => boundBtn(s, 3) },
  { name: "button-latched-toggle", about: "A latching toggle (button 20 always on) can never be bound, even by flipping it off and on",
    open: { devices: [DEV.virpil({ buttons: Array.from({ length: 32 }, (_, i) => i === 20 ? 1 : 0) })] },
    run: async page => { await toButton(page); await h.play(page, [btn(0, 30, 20, false), btn(0, 60, 20, true)]); return h.wizState(page); },
    expect: s => boundBtn(s, 20) },
  { name: "button-glitch", about: "Button 7 reads pressed for one frame (contact bounce elsewhere), then user presses 2",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toButton(page); await h.play(page, [btn(0, 5, 7, true), btn(0, 6, 7, false), ...press(0, 20, 2)]); return h.wizState(page); },
    expect: s => boundBtn(s, 2) },
  { name: "button-chatter", about: "Button 2 chatters 1/0/1/0/1 on press",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toButton(page); await h.play(page, [btn(0, 5, 2, true), btn(0, 6, 2, false), btn(0, 7, 2, true), btn(0, 8, 2, false), btn(0, 9, 2, true), btn(0, 30, 2, false)]); return h.wizState(page); },
    expect: s => boundBtn(s, 2) },
  { name: "button-two-same-frame", about: "Buttons 11 and 4 pressed in the same frame; user keeps 11 held, 4 is brushed for 50 ms",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toButton(page); await h.play(page, [btn(0, 5, 11, true), btn(0, 5, 4, true), btn(0, 5 + ms(50), 4, false), btn(0, 5 + ms(400), 11, false)]); return h.wizState(page); },
    expect: s => boundBtn(s, 11) },
  { name: "button-hat-as-axis", about: "User presses the hat (axis 9) in the button wizard",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toButton(page); await h.play(page, [...hold(0, 5, ms(300), { 9: -1 }), ...hold(0, 5 + ms(300), 2, { 9: HAT_IDLE })]); return h.wizState(page); },
    expect: s => s.stage === "name" ? true : "never finished: hat directions reported as an axis cannot be bound as buttons" },
  // ---------- flow ----------
  { name: "back-then-redo", about: "X captured, Back, choose Stick again: fresh state, binds again",
    open: { devices: [DEV.virpil()] },
    run: async page => {
      await toStick(page); await h.play(page, throwAxis(0, 5, AX.x, 0, 1));
      await h.clickAction(page, "Back"); await h.chooseType(page, "Stick");
      const fresh = await h.wizState(page);
      await h.play(page, stickXY(0)); return { fresh, s: await h.wizState(page) };
    },
    expect: o => o.fresh.step === 0 && Object.keys(o.fresh.axes).length === 0 && bound(o.s, { x: 0, y: 1 }) === true ? true : JSON.stringify(o) },
  { name: "escape-cancels", about: "Esc closes the wizard mid-step and nothing is added",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, throwAxis(0, 5, AX.x, 0, 1)); await page.keyboard.press("Escape"); return { s: await h.wizState(page), w: await h.widgets(page) }; },
    expect: o => o.s === null && o.w.length === 0 ? true : JSON.stringify(o) },
  { name: "no-timeout-feedback", about: "Step left open 10 s with no input: still waiting, no hint shown",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toStick(page); await h.frames(page, ms(10000)); return page.evaluate(() => ({ step: wiz.step, text: $("#wiz-body").innerText })); },
    expect: o => /not moving|try|nothing/i.test(o.text) ? true : "no feedback after 10 s (no timeout, no hint)" },
  { name: "gesture-gate-first-run", about: "Chrome hides pads until a gesture; user opens Stick step first, then moves X",
    open: { devices: [DEV.virpil()], gestureGate: true },
    run: async page => { await toStick(page); await h.play(page, stickXY(0)); return h.wizState(page); },
    expect: s => bound(s, { x: 0, y: 1 }) },
  { name: "gesture-gate-xbox", about: "Pads hidden until a gesture (no axis rests past 0.5); Stick step opened first, then left stick right",
    open: { devices: [DEV.xbox()], gestureGate: true },
    run: async page => { await toStick(page); await h.play(page, stickXY(0)); return h.wizState(page); },
    expect: s => bound(s, { x: 0, y: 1 }) },
  { name: "gesture-gate-zero-report", about: "VIRPIL reads all-zero until first report and is hidden until a gesture; Stick step opened, then X right",
    open: { devices: [DEV.virpil({ zeroUntilReport: true })], gestureGate: true },
    run: async page => { await toStick(page); await h.play(page, stickXY(0)); return h.wizState(page); },
    expect: s => bound(s, { x: 0, y: 1 }) },
  { name: "gesture-gate-button", about: "Pads hidden until gesture; button wizard opened first, then button 3 pressed",
    open: { devices: [DEV.virpil()], gestureGate: true },
    run: async page => { await toButton(page); await h.play(page, press(0, 5, 3)); return h.wizState(page); },
    expect: s => boundBtn(s, 3) },
  { name: "connect-mid-step", about: "Pedals plugged in after the Pedals step opened",
    open: { devices: [DEV.virpil()] },
    run: async page => { await toType(page, "Pedals"); await h.play(page, [plug(5, DEV.trudder()), ...throwAxis(1, 30, AX.rudder, 0, 1)]); return h.wizState(page); },
    expect: s => s.step >= 1 && s.axes.r === AX.rudder ? true : `stage ${s.stage} step ${s.step} axes ${JSON.stringify(s.axes)}` },
  { name: "replug-other-slot", about: "Rudder captured; USB re-enumerates and pedals come back in a different slot",
    open: { devices: [DEV.throttle(-1), DEV.trudder()] },
    run: async page => {
      await toType(page, "Pedals");
      await h.play(page, [...throwAxis(1, 5, AX.rudder, 0, 1), unplug(5 + ms(700), 1), unplug(6 + ms(700), 0), plug(8 + ms(700), DEV.trudder(), 0), plug(9 + ms(700), DEV.throttle(-1), 1),
        ...throwAxis(0, 20 + ms(800), AX.bl, -1, 1)]);
      return h.wizState(page);
    },
    expect: s => s.step >= 2 && s.axes.bl === AX.bl ? true : `stuck at step ${s.step} after replug (dev slot ${s.dev && s.dev.slot})` },
  // ---------- twins / slots ----------
  { name: "twin-wizard-second", about: "Two identical VIRPILs; user moves the one in slot 1; slot 0 is wobbled during Y",
    open: { devices: [DEV.virpil(), DEV.virpil()] },
    run: async page => { await toStick(page); await h.play(page, [...throwAxis(1, 5, AX.x, 0, 1), ...throwAxis(0, 5 + ms(900), AX.x, 0, 1), ...throwAxis(1, 5 + ms(1800), AX.y, 0, -1)]); return h.wizState(page); },
    expect: s => bound(s, { x: 0, y: 1 }) === true && s.dev.nth === 1 ? true : JSON.stringify(s) },
  { name: "twin-unplug-runtime", about: "Left (nth 0, slot 0) and Right (nth 1, slot 1); left stick unplugged",
    open: { devices: [DEV.virpil(), DEV.virpil()], profile: twinProfile() },
    run: async page => { const before = await h.resolve(page); await h.play(page, [unplug(2, 0)]); return { before, after: await h.resolve(page) }; },
    expect: o => o.after[0].slot === null && o.after[1].slot === 1 ? true : `after unplugging slot 0: ${o.after.map(r => r.label + "->" + r.slot).join(", ")}` },
  { name: "twin-replug-same-slot", about: "Left stick unplugged then replugged (comes back in slot 0)",
    open: { devices: [DEV.virpil(), DEV.virpil()], profile: twinProfile() },
    run: async page => { await h.play(page, [unplug(2, 0), plug(30, DEV.virpil(), 0)]); return h.resolve(page); },
    expect: r => r[0].slot === 0 && r[1].slot === 1 ? true : JSON.stringify(r) },
  { name: "twin-replug-other-slot", about: "Left stick unplugged; a throttle takes slot 0; Left comes back in slot 2",
    open: { devices: [DEV.virpil(), DEV.virpil()], profile: twinProfile() },
    run: async page => { await h.play(page, [unplug(2, 0), plug(10, DEV.throttle(-1), 0), plug(20, DEV.virpil(), 2)]); return h.resolve(page); },
    expect: r => r[0].slot === 2 && r[1].slot === 1 ? true : `Left->${r[0].slot}, Right->${r[1].slot}` },
  { name: "twin-swap-button", about: "Twins enumerated in the other order; Swap With Identical Device fixes it",
    open: { devices: [DEV.virpil(), DEV.virpil()], profile: twinProfile(), query: "?edit" },
    run: async page => { await page.evaluate(() => swapTwins(profile.widgets[0].match)); return h.resolve(page); },
    expect: r => r[0].slot === 1 && r[1].slot === 0 ? true : JSON.stringify(r) },
  { name: "remap-to-twin", about: "Detect Device on Left Stick, user moves the slot-1 twin",
    open: { devices: [DEV.virpil(), DEV.virpil()], profile: twinProfile(), query: "?edit" },
    run: async page => { await page.evaluate(() => startRemap(profile.widgets[0])); await h.play(page, stickXY(1)); return h.widgets(page); },
    expect: w => w[0].nth === 1 && w[0].axes.x === 0 && w[0].axes.y === 1 ? true : JSON.stringify(w[0]) },
  { name: "five-pads", about: "Five devices, Chrome exposes 4 slots; widget for the 5th shows the slots-full warning",
    open: { devices: [DEV.virpil(), DEV.virpil(), DEV.trudder(), DEV.throttle(-1), DEV.xbox()], query: "?edit",
      profile: { savedAt: Date.now(), settings: {}, widgets: [{ id: "X", type: "button", label: "Pad", x: 50, y: 50, match: DEV.xbox().id, nth: 0, button: 0, size: 1 }] } },
    run: async page => { await page.evaluate(() => setSelection([], "devices")); await h.frames(page, 20); return page.evaluate(() => $("#dev-body").innerText); },
    expect: t => /slots are taken/.test(t) ? true : t.slice(0, 200) },
  { name: "firefox-id", about: "Profile made in Chrome, opened where the pedals report a Firefox-style id",
    open: { devices: [DEV.firefoxRudder()], profile: { savedAt: Date.now(), settings: {}, widgets: [{ id: "P", type: "pedals", label: "Pedals", x: 50, y: 50, match: DEV.trudder().id, nth: 0, axes: { r: 5, bl: 0, br: 1 }, inv: {}, size: 1 }] } },
    run: async page => h.resolve(page),
    expect: r => r[0].slot === 0 ? true : JSON.stringify(r) }
];
